function model(p) {
  // Deterministic hourly support queue, Monday 00:00 to Friday 24:00 (120 hours), starting empty.
  // Arrivals follow a fixed daily shape scaled to the peak rate; agents work every hour (simplification).
  // Capacity = agents × 60 / handle minutes. backlog(t) = max(0, backlog(t−1) + arrivals(t) − capacity).
  const SHAPE = [0.12, 0.10, 0.08, 0.08, 0.10, 0.15, 0.25, 0.45, 0.70, 0.90, 1.00, 1.00, 0.95, 0.95, 1.00, 0.90, 0.75, 0.60, 0.45, 0.35, 0.28, 0.22, 0.18, 0.15];
  const DAY = [1.0, 0.98, 0.97, 0.99, 0.95], DAYS = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri'];
  const agents = Math.round(p.agents), peak = p.peakPerHour, handle = p.handleMin;
  const hours = [];
  for (let d = 0; d < 5; d++) for (let h = 0; h < 24; h++) hours.push({ i: d * 24 + h, day: DAYS[d], d, h, arrivals: Math.round(peak * SHAPE[h] * DAY[d]) });
  const run = a => {
    const capacity = a * 60 / handle, backlog = [];
    let b = 0, peakB = 0, peakAt = 0, resolved = 0;
    hours.forEach(x => { const nb = Math.max(0, b + x.arrivals - capacity); resolved += b + x.arrivals - nb; b = nb; backlog.push(b); if (b > peakB) { peakB = b; peakAt = x.i; } });
    const morning = [1, 2, 3, 4].map(d => backlog[d * 24 + 6]); // waiting at 07:00 Tue–Fri (end of hour 06)
    return { agents: a, capacity, backlog, peak: peakB, peakAt, end: backlog[119], morning, resolved,
      clearsNightly: morning.every(v => v === 0) };
  };
  const base = run(agents), plus = run(agents + 1);
  const totalArrivals = hours.reduce((s, x) => s + x.arrivals, 0);
  const util = totalArrivals / (base.capacity * 120);
  const duration = 12, perHour = duration / 120;
  const markers = [0, 2.4, 4.8, 7.2, 9.6].concat(base.peak > 0 ? [+((base.peakAt + 1) * perHour).toFixed(2)] : []).filter((v, i, a) => a.indexOf(v) === i).sort((a, b) => a - b);
  const when = i => hours[i].day + ' ' + String(hours[i].h + 1).padStart(2, '0') + ':00';
  const r = v => Math.round(v);
  const summary = base.peak === 0
    ? agents + ' agents (' + +base.capacity.toFixed(1) + ' tickets/h) keep up all week: the backlog never builds.'
    : agents + ' agents' + (base.clearsNightly ? ' clear the backlog every night (peak ' + r(base.peak) + ')' : ' never catch up: ' + r(base.morning[3]) + ' tickets still wait at 07:00 Friday, peak ' + r(base.peak)) +
      '; with ' + (agents + 1) + (plus.peak === 0 ? ' it never builds.' : ' the peak is ' + r(plus.peak) + (plus.clearsNightly ? ' and it clears every night.' : ' and it still carries over.'));
  return { hours, base, plus, agents, handle, peakRate: peak, totalArrivals, util, duration, perHour, markers, summary,
    peakWhen: when(base.peakAt), maxArrivals: Math.max(...hours.map(x => x.arrivals)) };
}

