function check(p) {
  const m = model(p);
  const verify = run => {
    const cap = run.agents * 60 / p.handleMin;
    let prev = 0, ok = Math.abs(run.capacity - cap) < 1e-9, mx = 0, at = 0;
    m.hours.forEach((x, i) => {
      const want = Math.max(0, prev + x.arrivals - cap);
      if (Math.abs(run.backlog[i] - want) > 1e-9) ok = false;
      if (want > mx) { mx = want; at = i; }
      prev = want;
    });
    return ok && Math.abs(run.peak - mx) < 1e-9 && run.peakAt === at;
  };
  const okBase = verify(m.base), okPlus = verify(m.plus);
  return { pass: okBase && okPlus,
    detail: 'At every one of 120 hours backlog = max(0, previous + arrivals − ' + m.base.capacity.toFixed(1) + '/h); the reported peak of ' + Math.round(m.base.peak) +
      ' tickets' + (m.base.peak > 0 ? ' (' + m.peakWhen + ')' : '') + ' matches, and with ' + (m.agents + 1) + ' agents (' + m.plus.capacity.toFixed(1) + '/h) the peak is ' + Math.round(m.plus.peak) + '.' };
}
